<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driver\Html;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptParams;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptUsecase;

class InvitationAcceptHtml
{
    public function __construct(
        private readonly InvitationAcceptUsecase $usecase,
        private readonly DecorateHtml $decorator,
        private readonly OidcCookieManager $cookies,
        private readonly Context $context,
    ) {
    }

    public function form(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant      = $args['tenant'];
        $query       = $request->getQueryParams();
        $rawToken    = (string) ($query['token'] ?? '');
        $clientId    = (string) ($query['client_id'] ?? '');
        $redirectUri = (string) ($query['redirect_uri'] ?? '');

        if ($rawToken === '') {
            return $this->renderError($request, $response, $tenant, 'Invalid invitation link.');
        }

        $html = $this->buildForm($rawToken, $tenant, $clientId, $redirectUri);
        $response->getBody()->write(
            $this->decorator->getFullPage($request, 'Accept invitation', $html, 'en', 'index', $tenant)
        );
        return $response;
    }

    public function accept(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $body   = (array) ($request->getParsedBody() ?? []);

        $rawToken    = (string) ($body['token'] ?? '');
        $password    = (string) ($body['password'] ?? '');
        $clientId    = (string) ($body['client_id'] ?? '');
        $redirectUri = (string) ($body['redirect_uri'] ?? '');

        if ($rawToken === '' || $password === '') {
            return $this->renderError($request, $response, $tenant, 'Token and password are required.');
        }

        try {
            $params = new InvitationAcceptParams(
                rawToken: $rawToken,
                tenantName: $tenant,
                password: $password,
                clientId: $clientId,
                redirectUri: $redirectUri,
            );
            $result = $this->usecase->accept($params);
            if ($result->session !== null && $clientId !== '' && $redirectUri !== '') {
                $state        = bin2hex(random_bytes(16));
                $nonce        = bin2hex(random_bytes(16));
                $baseUrl      = rtrim($this->context->getBaseUrl(), '/');
                $authorizeUrl = $baseUrl . '/oauth/openid/' . rawurlencode($tenant) . '/authorize?' . http_build_query([
                    'response_type' => 'code',
                    'client_id'     => $clientId,
                    'redirect_uri'  => $redirectUri,
                    'scope'         => 'openid email',
                    'state'         => $state,
                    'nonce'         => $nonce,
                ]);
                $response = $response->withStatus(302)->withHeader('Location', $authorizeUrl);
                return $this->cookies->authenticatedSessionCookie($tenant, $result->session->sessionId, $result->session->expiration)->attach($response);
            }
            $response = $this->renderSuccess($request, $response, $tenant, $result->email, $redirectUri);
            if ($result->session !== null) {
                $response = $this->cookies->authenticatedSessionCookie($tenant, $result->session->sessionId, $result->session->expiration)->attach($response);
            }
            return $response;
        } catch (\DomainException $e) {
            return $this->renderError($request, $response, $tenant, $e->getMessage());
        }
    }

    private function buildForm(string $rawToken, string $tenant, string $clientId, string $redirectUri): string
    {
        $token       = htmlspecialchars($rawToken);
        $clientIdVal = htmlspecialchars($clientId);
        $redirectVal = htmlspecialchars($redirectUri);
        $action      = './accept';
        return <<<HTML
            <h1>Accept invitation</h1>
            <p>Create your password to activate your account.</p>
            <form method="POST" action="{$action}">
                <input type="hidden" name="token" value="{$token}" />
                <input type="hidden" name="client_id" value="{$clientIdVal}" />
                <input type="hidden" name="redirect_uri" value="{$redirectVal}" />
                <label>Password
                    <input type="password" name="password" required autocomplete="new-password" />
                </label>
                <label>Confirm password
                    <input type="password" name="password_confirm" required autocomplete="new-password" />
                </label>
                <input class="primary-button" type="submit" value="Activate account" />
            </form>
            HTML;
    }

    private function renderSuccess(ServerRequestInterface $request, ResponseInterface $response, string $tenant, string $email, string $redirectUri): ResponseInterface
    {
        $parsed = parse_url($redirectUri);
        $appUrl = ($parsed['scheme'] ?? 'https') . '://' . ($parsed['host'] ?? '')
            . (isset($parsed['port']) ? ':' . $parsed['port'] : '');
        $appUrlEsc = htmlspecialchars($appUrl !== '://' ? $appUrl : '');

        $buttonHtml = $appUrlEsc !== ''
            ? '<a class="primary-button" href="' . $appUrlEsc . '">Login now</a>'
            : '';

        $emailEsc = htmlspecialchars($email);
        $html = '<h1>Account activated</h1>'
            . '<p>Your account has been created successfully.</p>'
            . '<p>Use <strong>' . $emailEsc . '</strong> as your username to log in.</p>'
            . $buttonHtml;

        $response->getBody()->write(
            $this->decorator->getFullPage($request, 'Account activated', $html, 'en', 'index', $tenant)
        );
        return $response;
    }

    private function renderError(ServerRequestInterface $request, ResponseInterface $response, string $tenant, string $message): ResponseInterface
    {
        $html = '<h1>Invitation</h1><p class="error">' . htmlspecialchars($message) . '</p>';
        $response->getBody()->write(
            $this->decorator->getFullPage($request, 'Invitation', $html, 'en', 'index', $tenant)
        );
        return $response->withStatus(400);
    }
}
